class BusinessSetupScreen extends StatefulWidget { const BusinessSetupScreen({super.key,required this.organization}); final Organization organization; @override State<BusinessSetupScreen> createState()=>_BusinessSetupScreenState();} class _BusinessSetupScreenState extends State<BusinessSetupScreen>{late final TextEditingController name; late bool verified; @override void initState(){super.initState();name=TextEditingController(text:widget.organization.name);verified=widget.organization.verified;} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Business profile')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[CircleAvatar(radius:40,child:Text(name.text.isEmpty?'O':name.text[0])),const SizedBox(height:22),TextField(controller:name,onChanged:(_)=>setState((){}),decoration:const InputDecoration(labelText:'Organization name',border:OutlineInputBorder())),SwitchListTile(value:verified,onChanged:(v)=>setState(()=>verified=v),title:const Text('Verification-style indicator'),subtitle:const Text('Visual prototype only')),const Spacer(),FilledButton(onPressed:() async {await ChatbotApi().updateProfile(widget.organization.id,name.text,verified);if(c.mounted)Navigator.pop(c);},child:const Text('Save business profile'))])));}
